return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'bs_BA','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:01+00:00','po-revision-date'=>'2026-10-31T05:53:01+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Popunjava nedostajuće prijevode za dodatke i teme koji su već instalirani na vašoj stranici.','Translations'=>'Prijevodi','Babilim Settings'=>'Postavke za Babilim','Settings'=>'Postavke','You are not allowed to do this.'=>'Nemate dozvolu za ovu radnju.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Odaberite manje komponenti: najviše %1$d operacija po pokretanju (odabrali ste %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Ta komponenta nije instalirana na ovoj stranici, pa se za nju ne može zatražiti prevod.','Already installed.'=>'Već je instalirano.','Downloaded and installed.'=>'Preuzeto i instalirano.','Babilim has not been enabled for this site yet.'=>'Babilim još nije omogućen za ovu stranicu.','No build is available to download for this locale.'=>'Nema dostupne verzije za preuzimanje za ovaj jezik.','Rolled back to the previous build.'=>'Vraćeno na prethodnu verziju.','Rolled back and reported.'=>'Vraćeno na prethodnu verziju i prijavljeno.','Rolled back, but the report could not be sent: %s'=>'Vraćeno na prethodnu verziju, ali prijavu nije bilo moguće poslati: %s','Removed.'=>'Uklonjeno.','Translation requested.'=>'Prijevod je zatražen.','This component was already uploaded. Babilim is checking it now.'=>'Ova komponenta je već otpremljena. Babilim je upravo provjerava.','Upload cancelled.'=>'Otpremanje je otkazano.','Upload complete — translation requested.'=>'Otpremanje je završeno — prevod je zatražen.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Ova komponenta ne navodi broj verzije, pa se za nju ne može zatražiti prevod.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Broj verzije ove komponente duži je od %d znakova, što Babilim ne može obraditi, pa se za nju ne može zatražiti prevod.','A translation cannot be requested for that locale on this site right now.'=>'Prijevod za taj jezik trenutno se ne može zatražiti na ovoj stranici.','Thank you. Your report was sent.'=>'Hvala vam. Vaša prijava je poslana.','This report does not name a valid plugin or theme and locale.'=>'Ova prijava ne navodi važeći dodatak ili temu i jezik.','Please choose a category for this report.'=>'Odaberite kategoriju za ovu prijavu.','This report is missing a valid build to report against.'=>'Ovoj prijavi nedostaje važeća verzija na koju se prijava odnosi.','This build is not one this site currently knows about for this component/locale.'=>'Ova stranica trenutno ne poznaje ovu verziju za ovu komponentu/jezik.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Polje "%1$s" je predugo: ima %2$d znakova, a ograničenje je %3$d. Ništa nije poslano; skratite ga i pokušajte ponovo.','Original string'=>'Originalni string','String context'=>'Kontekst stringa','Current translation'=>'Trenutni prijevod','Suggested translation'=>'Predloženi prevod','Note (optional)'=>'Napomena (neobavezno)','Where you saw this (optional)'=>'Gdje ste ovo vidjeli (neobavezno)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Servis je privremeno odgodio Babilim sinhronizaciju (ograničenje broja zahtjeva); pokušat će ponovo nakon %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'To nije valjan WordPress kod jezika. Ništa nije sačuvano.','Settings saved.'=>'Postavke su sačuvane.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ako je ovo uključeno, deinstalacija također briše identitet ove stranice. Plaćena licenca vezana za ovu stranicu nakon toga se ne može automatski vratiti; morali biste kontaktirati Babilim podršku na %s da biste je povratili.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim je postavljen da izbriše identitet ove stranice kada se dodatak izbriše. Plaćena licenca vezana za ovu stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %s. Da zadržite identitet, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim i ponovo deaktivirajte. Deaktivirati svejedno?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d stranica na ovoj mreži postavljena je da izbriše svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za tu stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da zadržite identitet, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim te stranice i ponovo deaktivirajte. Deaktivirati svejedno?' . "\0" . '%1$d stranice na ovoj mreži postavljene su da izbrišu svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za te stranice tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da zadržite identitete, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim svake stranice i ponovo deaktivirajte. Deaktivirati svejedno?' . "\0" . '%1$d stranica na ovoj mreži postavljeno je da izbriše svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za te stranice tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %2$s. Da zadržite identitete, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim svake stranice i ponovo deaktivirajte. Deaktivirati svejedno?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Ova mreža ima previše stranica da bi se provjeravale jedna po jedna, a neke od njih možda su postavljene da izbrišu svoj Babilim identitet kada se dodatak izbriše. Plaćena licenca vezana za takvu stranicu tada se ne bi mogla automatski vratiti; morali biste kontaktirati Babilim podršku na %s. Da zadržite identitete, pritisnite Otkaži, isključite "Izbriši sve Babilim podatke pri deinstalaciji" u postavkama za Babilim svake stranice i ponovo deaktivirajte. Deaktivirati svejedno?','Open Babilim settings'=>'Otvori postavke za Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim nije mogao verificirati ovu web-lokaciju, pa se ništa ne preuzima niti instalira.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Servis nije mogao doprijeti do vaše stranice. Zahtjev vjerovatno blokira zaštitni zid, sigurnosni dodatak ili pravilo hosta; molimo dozvolite zahtjeve prema /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Vaša web-lokacija je predugo odgovarala. Pokušajte ponovo kasnije i provjerite da host nije prespor ili preopterećen.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Vaša stranica je odgovorila, ali ne očekivanim sadržajem. REST API možda mijenja drugi dodatak ili je ta krajnja tačka keširana; molimo isključite /wp-json/babilim/v1/challenge iz keširanja i prepisivanja.','Please check that your site can be reached from the internet, then try again.'=>'Provjerite da je vaša web-lokacija dostupna s interneta, pa pokušajte ponovo.','Re-verify'=>'Ponovo verificiraj','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Ova stranica premašuje veličinu koju servis prihvata u jednoj sinhronizaciji, pa su neke stavke izostavljene: %1$d komponenti i %2$d jezika.','This site is verified.'=>'Ova web-lokacija je verificirana.','Registration restarted.'=>'Registracija je ponovo pokrenuta.','Sync complete.'=>'Sinhronizacija završena.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim omogućava i provjerava ovu web-lokaciju… Ponovo učitajte stranicu ili sačekajte da se zakazana provjera završi.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim nije mogao završiti omogućavanje (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Host koji obrađuje samo jedan PHP zahtjev istovremeno ne može završiti ovaj korak.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim je omogućen: ova stranica je verifikovana i pronađena je %d komponenta.' . "\0" . 'Babilim je omogućen: ova stranica je verifikovana i pronađene su %d komponente.' . "\0" . 'Babilim je omogućen: ova stranica je verifikovana i pronađeno je %d komponenti.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim je onemogućen. Ništa se više ne šalje; već instalirani prijevodi nastavljaju raditi.','Supplementary translation index rebuilt.'=>'Dopunski indeks prevoda je ponovo izgrađen.','Sweep complete: %d file deleted.'=>'Čišćenje završeno: %d datoteka obrisana.' . "\0" . 'Čišćenje završeno: %d datoteke obrisane.' . "\0" . 'Čišćenje završeno: %d datoteka obrisano.','Removed %d installed component.'=>'Uklonjena je %d instalirana komponenta.' . "\0" . 'Uklonjene su %d instalirane komponente.' . "\0" . 'Uklonjeno je %d instaliranih komponenti.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatske instalacije su sada isključene; ponovo ih uključite u postavkama ako ih želite.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim pronalazi dodatke i teme na ovoj web-lokaciji koji nemaju prijevod za vaš jezik i instalira po jedan za svaki.','Languages found on this site: %s.'=>'Jezici pronađeni na ovoj web-lokaciji: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Dostupni prevodi mogu se instalirati jednim klikom, a nedostajući se mogu zatražiti. Nakon toga se novi prevodi i ažuriranja instaliraju automatski (u besplatnom planu samo za dodatke i teme koji već koriste slobodno mjesto).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Besplatni plan pokriva ograničen broj dodataka i tema; vaša tačna kvota prikazana je u Postavkama nakon što omogućite Babilim.','What is sent when you enable Babilim'=>'Šta se šalje kada omogućite Babilim','Enabling…'=>'Omogućavanje…','Enable Babilim'=>'Omogući Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Klikom na Omogući pristajete da Babilimu pošaljete gore navedene informacije.','Check again now'=>'Provjeri ponovo odmah','Babilim installed %d translation automatically since your last visit.'=>'Babilim je automatski instalirao %d prijevod od vaše posljednje posjete.' . "\0" . 'Babilim je automatski instalirao %d prijevoda od vaše posljednje posjete.' . "\0" . 'Babilim je automatski instalirao %d prijevoda od vaše posljednje posjete.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim omogućava i provjerava ovu web-lokaciju… (posljednji pokušaj: %s)','Check again'=>'Provjeri ponovo','No components synced yet.'=>'Još nema sinhronizovanih komponenti.','%d succeeded'=>'%d uspjelo' . "\0" . '%d uspjela' . "\0" . '%d uspjelo','%d skipped'=>'%d preskočeno' . "\0" . '%d preskočena' . "\0" . '%d preskočeno','%d failed'=>'%d neuspjelo' . "\0" . '%d neuspjela' . "\0" . '%d neuspjelo','%d not yet tried'=>'%d još nije pokušano' . "\0" . '%d još nisu pokušana' . "\0" . '%d još nije pokušano','%1$s nothing to do.'=>'%1$s nema šta da se uradi.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Grupno preuzimanje:','Bulk update:'=>'Grupno ažuriranje:','Bulk request:'=>'Grupni zahtjev:','per day'=>'dnevno','Wrong meaning'=>'Pogrešno značenje','Wrong term'=>'Pogrešan termin','Broken placeholder'=>'Neispravan rezervirani tekst','Wrong for this context'=>'Pogrešno za ovaj kontekst','Wrong plural form'=>'Pogrešan oblik množine','Negation reversed'=>'Negacija je obrnuta','Translation does not load'=>'Prevod se ne učitava','problem report categoryOther'=>'Ostalo','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Nastavlja se…','Continue next batch (%d left)'=>'Nastavi sa sljedećom grupom (preostalo: %d)','Search components'=>'Pretraži komponente','These are the languages this site uses. You can change them in %s.'=>'Ovo su jezici koje ova stranica koristi. Možete ih promijeniti u %s.','Upload this component?'=>'Učitati ovu komponentu?','There is no upload waiting for confirmation.'=>'Nema učitavanja koje čeka potvrdu.','Back'=>'Nazad','To translate this component, Babilim needs its source.'=>'Da bi preveo ovu komponentu, Babilim treba njen izvorni kod.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Cijeli direktorij dodatka ili teme %1$s (verzija %2$s) bit će učitan na Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Ako taj direktorij sadrži ključeve, zapisnike ili podatke kupaca, i oni će biti učitani. Servis uklanja uobičajene osjetljive datoteke (konfiguraciju, okruženje, izvoze baze podataka, zapisnike, ključeve), ali ne može garantovati da će pronaći sve.','The upload is kept until you ask Babilim to delete it.'=>'Učitani sadržaj se čuva dok od Babilima ne zatražite da ga izbriše.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Pohranjuje ga hosting provajder servisa, a AI modeli ga obrađuju kako bi se dobio prijevod.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Originalni tekst i prijevodi nastali iz njega bit će dostupni drugim stranicama koje instaliraju istu verziju.','By continuing you confirm that you have the right to upload this component.'=>'Nastavkom potvrđujete da imate pravo učitati ovu komponentu.','Upload and request'=>'Učitaj i zatraži','Uploading…'=>'Učitavanje…','Cancel'=>'Otkaži','Uploading'=>'Učitavanje','There is no upload in progress.'=>'Nema učitavanja u toku.','Uploading part %1$d of %2$d…'=>'Učitavanje dijela %1$d od %2$d…','Continue'=>'Nastavi','Confirm'=>'Potvrdi','Remove'=>'Ukloni','Roll back'=>'Vrati na prethodno','Nothing to confirm.'=>'Nema ništa za potvrdu.','Choose a language'=>'Odaberite jezik','Roll back and report'=>'Vrati na prethodno i prijavi','Report a problem'=>'Prijavi problem','Nothing to choose.'=>'Nema ništa za odabir.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Odaberite jezik.','Supplementary translations'=>'Dopunski prevodi','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Doprinos svake komponente dopuni za zadanu domenu svakog jezika.','Component'=>'Komponenta','Language'=>'Jezik','Included in index'=>'Uključeno u indeks','Entries'=>'Unosi','Conflicting keys'=>'Ključevi u sukobu','Yes'=>'Da','No — component inactive'=>'Ne — komponenta je neaktivna','No — installed version differs from the active one'=>'Ne — instalirana verzija se razlikuje od aktivne','No — component removed'=>'Ne — komponenta je uklonjena','No'=>'Ne','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Ovo može učiniti samo administrator mreže jer se mijenjaju datoteke prijevoda koje dijele sve stranice na ovoj mreži.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim nije mogao završiti provjeru ove stranice (usluga joj nije mogla pristupiti). Registracija je pauzirana.','This site already has an active registration that can no longer be recovered automatically.'=>'Ova stranica već ima aktivnu registraciju koja se više ne može automatski oporaviti.','Restart registration'=>'Ponovo pokreni registraciju','Babilim settings'=>'Postavke za Babilim','General'=>'Općenito','Advanced'=>'Napredno','Languages'=>'Jezici','Automatic installs'=>'Automatske instalacije','Install available translations automatically'=>'Automatski instaliraj dostupne prevode','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Na besplatnom planu automatski se instaliraju samo komponente koje već koriste neko od vaših slobodnih mjesta, tako da se ne zauzima novo mjesto.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Ova stranica je dio multisite mreže, koja ne instalira nove prijevode automatski. Već instalirani prijevodi se i dalje ažuriraju.','Custom overrides'=>'Vlastita prepisivanja','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Zadrži moja vlastita prepisivanja prevoda pri brisanju svega ili deinstalaciji ovog dodatka.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Datoteke prijevoda koje stavite u %s uvijek imaju prednost nad Babilimovim. Zadržavaju se osim ako ovo ne isključite.','Uninstall'=>'Deinstalacija','Delete all Babilim data on uninstall'=>'Izbriši sve Babilim podatke pri deinstalaciji','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Isključeno prema zadanim postavkama: brisanjem dodatka zadržava se identitet ove stranice, pa ga ponovna instalacija može iskoristiti.','Account'=>'Račun','Save changes'=>'Sačuvaj promjene','Disable Babilim'=>'Onemogući Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Instalirani prijevodi se zadržavaju, ali se više neće provoditi provjere ni preuzimanja.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Onemogućiti Babilim? Instalirani prevodi se zadržavaju, ali se više neće provjeravati ni preuzimati nove verzije.','This site is not registered with Babilim yet.'=>'Ova stranica još nije registrirana kod Babilima.','This site is already licensed. Reload the page.'=>'Ova stranica je već licencirana. Ponovo učitajte stranicu.','Checkout is not available for this site right now.'=>'Plaćanje trenutno nije dostupno za ovu stranicu.','Could not start checkout: %s'=>'Nije moguće pokrenuti plaćanje: %s','Babilim is not enabled.'=>'Babilim nije omogućen.','Not registered yet'=>'Još nije registrovano','Not verified'=>'Nije verifikovano','Verified'=>'Verifikovano','Status'=>'Status','Licensed'=>'Licencirano','Partner'=>'Partner','Free'=>'Besplatno','License'=>'Licenca','Upgrade this site'=>'Nadogradi ovu stranicu','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednokratna kupovina za ovu stranicu: %1$s %2$s. Uključuje sva buduća ažuriranja prijevoda. Plaćanje obrađuje Paddle u novoj kartici.','This issues a new restore code and the previous one stops working. Continue?'=>'Ovo izdaje novi kod za vraćanje, a prethodni prestaje raditi. Nastaviti?','Show a new restore code'=>'Prikaži novi kod za vraćanje','rc_…'=>'rc_…','Restore code'=>'Kod za vraćanje','Restore purchase'=>'Vrati kupovinu','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Jeste li ranije kupili licencu za ovu domenu? Unesite kod za vraćanje koji ste dobili prilikom plaćanja.','That does not look like a restore code.'=>'Ovo ne izgleda kao kod za vraćanje.','This restore code was not recognised for this site.'=>'Ovaj kod za vraćanje nije prepoznat za ovu stranicu.','Too many attempts. Try again tomorrow.'=>'Previše pokušaja. Pokušajte ponovo sutra.','This site must be verified first.'=>'Ova stranica prvo mora biti verifikovana.','Could not restore the purchase: %s'=>'Nije moguće vratiti kupovinu: %s','Purchase restored. This site is now licensed.'=>'Kupovina je vraćena. Ova stranica je sada licencirana.','This site has no purchase to show a code for.'=>'Ova stranica nema kupovinu za koju bi se mogao prikazati kod.','Could not show a new restore code: %s'=>'Nije moguće prikazati novi kod za vraćanje: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Vaš novi kod za vraćanje: %s. Sačuvajte ga na sigurnom mjestu — prethodni kod više ne radi.','What is sent when Babilim checks this site'=>'Šta se šalje kada Babilim provjerava ovu stranicu','(detected)'=>'(otkriveno)','No language is managed yet.'=>'Još nijedan jezik nije pod upravljanjem.','Babilim adds translations for every language checked here.'=>'Babilim dodaje prijevode za svaki jezik označen ovdje.','Add another language'=>'Dodaj još jedan jezik','Choose a language…'=>'Odaberite jezik…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Nije moguće učitati cijelu listu jezika sa WordPress.org iz servisa, pa trenutno nije moguće dodati nijedan drugi jezik.','Theme'=>'Tema','Plugin'=>'Dodatak','Free quota'=>'Besplatna kvota','Downloads: %1$d/%2$d (%3$s)'=>'Preuzimanja: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Indeks dopunskih prevoda','Built'=>'Izgrađeno','Included'=>'Uključeno','Excluded'=>'Isključeno','Already in WordPress core'=>'Već u WordPress jezgru','Supplementary translation maintenance'=>'Održavanje dopunskih prevoda','Maintenance status is not available right now.'=>'Status održavanja trenutno nije dostupan.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Čišćenje je pauzirano %1$s: %2$s. Ništa nije izbrisano.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Posljednje čišćenje %1$s: %2$d novooznačeno, %3$d datoteka izbrisano, %4$d zapisa uklonjeno.','No cleanup has run yet.'=>'Čišćenje još nije pokrenuto.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Upis u indeks prevoda je došao u sukob s drugim zahtjevom %1$s (%2$s) i nije primijenjen; zadržana je najnovija verzija.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Upis u indeks prevoda %1$s (%2$s) nije mogao biti dovršen i nije primijenjen (%3$s).','Maintenance'=>'Održavanje','Rebuild index now'=>'Ponovo izgradi indeks','Sweep now'=>'Očisti sada','Danger zone'=>'Opasna zona','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Uklanja sve jezične datoteke koje je Babilim instalirao za svaki dodatak i temu na ovoj stranici.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Ukloniti sve što je Babilim instalirao? Ovo briše sve jezične datoteke koje je Babilim instalirao za svaki dodatak i temu na ovoj stranici.','Remove everything Babilim installed'=>'Ukloni sve što je Babilim instalirao','This string is too long to be sent as a report, so no report form is offered for it.'=>'Ovaj tekst je predugačak da bi se poslao kao izvještaj, pa za njega nije ponuđen obrazac za izvještaj.','Category'=>'Kategorija','Choose a category…'=>'Odaberite kategoriju…','Roll back and send report'=>'Vrati prethodno stanje i pošalji izvještaj','Send report'=>'Pošalji izvještaj','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Dio teksta ove komponente je ugrađen u kod od strane autora i ne može se prevesti pomoću jezičkog paketa.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Isporučeno uz temu','Bundled with the plugin'=>'Isporučeno uz dodatak','Upload was not accepted'=>'Otpremanje nije prihvaćeno','Upload expired before it finished'=>'Otpremanje je isteklo prije završetka','No translation'=>'Nema prijevoda','Upload in progress — continue or cancel'=>'Otpremanje je u toku — nastavite ili otkažite','Scheduled, waiting to be processed'=>'Zakazano, čeka obradu','Translating…'=>'Prevođenje…','Translation failed'=>'Prevođenje nije uspjelo','Free quota used'=>'Iskorištena besplatna kvota','Needs a paid license'=>'Potrebna je plaćena licenca','Not supported'=>'Nije podržano','Status unknown'=>'Status nepoznat','translation statusInstalled'=>'Instalirano','Update available'=>'Dostupno ažuriranje','Removed after a failed integrity check'=>'Uklonjeno nakon neuspjele provjere integriteta','Installed · built for %s, new version scheduled'=>'Instalirano · izgrađeno za %s, nova verzija je zakazana','Installed · built for a different version, new version scheduled'=>'Instalirano · izgrađeno za drugu verziju, nova verzija je zakazana','Installed · built for %s, translating the new version…'=>'Instalirano · izgrađeno za %s, prevodi se nova verzija…','Installed · built for a different version, translating the new version…'=>'Instalirano · izgrađeno za drugu verziju, prevodi se nova verzija…','Installed · built for %1$s, this site has %2$s'=>'Instalirano · izgrađeno za %1$s, ova stranica ima %2$s','Installed · built for %s'=>'Instalirano · izgrađeno za %s','Installed · built for a different version'=>'Instalirano · izgrađeno za drugu verziju','Installed · built for %s, new version failed'=>'Instalirano · izrađeno za %s, nova verzija nije uspjela','Installed · built for a different version, new version failed'=>'Instalirano · izrađeno za drugu verziju, nova verzija nije uspjela','Installed · built for %s, new version needs a paid license'=>'Instalirano · izrađeno za %s, nova verzija zahtijeva plaćenu licencu','Installed · built for a different version, new version needs a paid license'=>'Instalirano · izrađeno za drugu verziju, nova verzija zahtijeva plaćenu licencu','Installed · built for %s, free quota used'=>'Instalirano · napravljeno za %s, besplatna kvota iskorištena','Installed · built for a different version, free quota used'=>'Instalirano · napravljeno za drugu verziju, besplatna kvota iskorištena','translation statusAvailable'=>'Dostupno','Installed · %s'=>'Instalirano · %s','Available · %s'=>'Dostupno · %s','Update'=>'Ažuriraj','Download'=>'Preuzmi','Updating…'=>'Ažuriranje…','Downloading…'=>'Preuzimanje…','Retry request'=>'Ponovi zahtjev','Request newer translation'=>'Zatraži noviji prijevod','Request translation'=>'Zatraži prevod','Requesting…'=>'Traženje…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Zahtjev za prevod koristi jedno od vaših slobodnih mjesta, osim ako ga ova komponenta već koristi. Neuspjeli prevod ne vraća mjesto.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Ako ova komponenta još ne koristi jedno od vaših slobodnih mjesta, zahtjev za prevod će ga iskoristiti. Neuspjeli prevod ne vraća mjesto. Nastaviti?','No plugins or themes found.'=>'Nisu pronađeni dodaci ni teme.','Clear filters'=>'Očisti filtere','No components match these filters. %s'=>'Nijedna komponenta ne odgovara ovim filterima. %s','Select all'=>'Odaberi sve','All'=>'Sve','Available'=>'Dostupno','Updates'=>'Ažuriranja','Requestable'=>'Može se zatražiti','Installed'=>'Instalirano','Plugins'=>'Dodaci','Themes'=>'Teme','All languages'=>'Svi jezici','%d to install'=>'%d za instalaciju' . "\0" . '%d za instalaciju' . "\0" . '%d za instalaciju','Language:'=>'Jezik:','Bulk actions apply to every matching language of each selected component.'=>'Grupne akcije se primjenjuju na svaki odgovarajući jezik svake odabrane komponente.','Bulk actions apply only to the selected language of each selected component.'=>'Grupne akcije se primjenjuju samo na odabrani jezik svake odabrane komponente.','Version %s'=>'Verzija %s','Theme · %s'=>'Tema · %s','Plugin · %s'=>'Dodatak · %s','Remove the %2$s translation of %1$s from this site?'=>'Ukloniti prijevod %2$s za %1$s s ove stranice?','Roll back the %2$s translation of %1$s to the previous build?'=>'Vratiti prevod %2$s za %1$s na prethodnu verziju?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Izazov za registraciju nije u očekivanom obliku.','That is not a valid build identifier.'=>'To nije valjan identifikator verzije.','Refusing to write outside the Babilim language-file directory.'=>'Odbijeno pisanje izvan direktorija jezičkih datoteka Babilim.','Could not write the downloaded package to disk.'=>'Preuzeti paket nije moguće upisati na disk.','Unexpected HTTP %d response.'=>'Neočekivan HTTP odgovor %d.','This site\'s URL, so the service can verify you own it.'=>'URL ove stranice, kako bi usluga mogla provjeriti da ste vi njen vlasnik.','Your WordPress version, to serve compatible translation files.'=>'Vaša verzija WordPressa, radi isporuke kompatibilnih datoteka prijevoda.','Your PHP version, for compatibility.'=>'Vaša verzija PHP-a, radi kompatibilnosti.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Verzija samog ovog dodatka, kako bi vam usluga mogla reći da ga ažurirate ako je prestar za komunikaciju.','This site\'s configured locale.'=>'Konfigurirani jezik (locale) ove stranice.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Svaki jezik (locale) koji se koristi na ovoj stranici (jezik stranice, instalirani jezični paketi, jezici korisnika i svi koje ručno dodate). Nijedan jezik se ne tretira drugačije od ostalih.','(a public key generated for this site)'=>'(javni ključ generiran za ovu stranicu)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Javni ključ instalacije ove stranice, koji služi kao dokaz da zahtjevi zaista dolaze s ove stranice. Šalje se isključivo javni dio.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Svaki instalirani dodatak/tema: njegov slug, verzija, tekstualne domene, da li je na WordPress.org, njegovi vlastiti uključeni jezici i za koje jezike ste već instalirali Babilim prevod.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Samo kada potvrdite otpremanje za dodatak ili temu koja nije na WordPress.org: cijeli direktorij te komponente, kao zip.','(generic codes and coordinates only)'=>'(samo generički kodovi i koordinate)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Do 20 dijagnostičkih događaja na čekanju (npr. datoteka koja nije prošla provjeru integriteta), svaki samo kao kod, komponenta i jezik, nikada sadržaj stringova ni prevedeni tekst.','Unsafe locale: %s'=>'Nesiguran jezik (locale): %s','Manifest unavailable: %s'=>'Manifest nije dostupan: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Nije moguće odrediti aktivne komponente; postojeći spojeni indeks je ostavljen nepromijenjen.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Nije moguće odrediti instalirane dodatke/teme; čišćenje je preskočeno, ništa nije obrisano.','Sweep aborted without orphaning anything: %s.'=>'Čišćenje prekinuto bez označavanja ijedne stavke osirotjelom: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Čišćenje je izvršeno, ali neke njegove promjene nisu mogle biti zabilježene u indeksu prevoda; sljedeće čišćenje će ih ponovo pokušati.','component kind in the sweep brake messagetheme'=>'temu','component kind in the sweep brake messageplugin'=>'dodatak','it would orphan every managed %1$s component (%2$d of %2$d)'=>'osirotjele bi bile sve upravljane komponente tipa %1$s (%2$d od %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'osirotjele bi bile %1$d od %2$d upravljanih komponenti (više od polovine)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Spojeni indeks za \'%s\' je ponovo izgrađen, ali ga indeks prevoda nije mogao zabilježiti; sljedeća izgradnja će pokušati ponovo.','Could not write the staged merged index.'=>'Nije moguće zapisati pripremljeni spojeni indeks.','Re-parsed entry count did not match the built index.'=>'Broj ponovo parsiranih unosa ne odgovara izgrađenom indeksu.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Nije moguće premjestiti spojeni indeks za \'%s\' na mjesto; prethodni posluženi indeks (ako postoji) je uklonjen umjesto da bude ostavljen napola ažuriran. Za ovaj jezik se ne poslužuje dopuna za zadanu domenu do sljedeće uspješne izgradnje.','Could not open zip: %s'=>'Nije moguće otvoriti zip: %s','Zip has no manifest.json.'=>'Zip nema manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json u zip datoteci nije valjan JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'Polje \'%s\' u manifest.json se ne podudara s očekivanom vrijednošću.','Another installation is running; try again in a moment.'=>'Druga instalacija je u toku; pokušajte ponovo za trenutak.','Not a valid server_build_id: %s'=>'Nevaljan server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Vrsta \'%1$s\' u manifestu paketa se ne podudara sa zatraženom vrstom \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Tekstualna domena paketa \'%1$s\' ne podudara se s kopijom komponente na ovoj stranici (\'%2$s\'), pa paket nije instaliran.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Zadana domena \'%1$s\' ne odgovara ni slugu manifesta paketa \'%2$s\' ni njegovom text_domain \'%3$s\'.','Unsafe slug: %s'=>'Nesiguran slug: %s','Unsafe text_domain: %s'=>'Nesiguran text_domain: %s','The package has no %s for its own text domain.'=>'Paket nema %s za vlastitu tekstualnu domenu.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json nedostaje ili ima nevažeće polje \'%s\'.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json nedostaje ili ima nevažeće \'entries\'.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json nedostaje ili ima nevažeće \'files\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json nedostaje ili ima nevažeće \'extra_domains\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json nedostaje ili ima nevažeći \'build_no\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' u manifest.json nije važeći ID izgradnje.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' u manifest.json nije važeći niz verzije.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' u manifest.json mora biti \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' u manifest.json mora biti \'plugin\' ili \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ima nevažeći \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ima nevažeći \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest nedostaje ili ima nevažeće polje \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' u expected_manifest nije važeći ID izgradnje.','No record for %s'=>'Nema zapisa za %s','One or more served files no longer match the manifest.'=>'Jedna ili više isporučenih datoteka se više ne podudara s manifestom.','No previous build to roll back to.'=>'Nema prethodne izgradnje na koju se može vratiti.','The change could not be recorded in the translation index; please try again.'=>'Promjena nije mogla biti zabilježena u indeksu prevoda; pokušajte ponovo.','Unknown kind: %s'=>'Nepoznata vrsta: %s','Unsafe domain: %s'=>'Nesiguran domen: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Tekstualna domena \'%1$s\' (%2$s) već se isporučuje za drugu instaliranu komponentu (%3$s); ništa nije instalirano.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Vraćanje na prethodno stanje prepisalo bi \'%1$s\' (%2$s), što se sada isporučuje za drugu instaliranu komponentu (%3$s); ništa nije promijenjeno.','Zip is missing expected file: %s'=>'Zip nema očekivanu datoteku: %s','sha256 mismatch for %s'=>'sha256 se ne podudara za %s','The package declares no main translation file.'=>'Paket ne navodi glavnu datoteku prijevoda.','Zip is missing expected default file: %s'=>'Zip nema očekivanu zadanu datoteku: %s','sha256 mismatch for default/%s'=>'sha256 se ne podudara za default/%s','Could not stage %s'=>'Nije moguće pripremiti %s','Could not stage default/%s'=>'Nije moguće pripremiti default/%s','Entry count mismatch for %s'=>'Broj unosa se ne podudara za %s','Could not verify entry count for %s'=>'Nije moguće provjeriti broj unosa za %s','l10n.php entry count mismatch for %s'=>'Broj unosa u l10n.php se ne podudara za %s','Default supplement entry count mismatch.'=>'Broj unosa zadanog dodatka se ne podudara.','The package produced no servable main translation file.'=>'Paket nije proizveo glavnu datoteku prijevoda koja se može isporučiti.','Could not prepare %s for rollback.'=>'Nije moguće pripremiti %s za vraćanje na prethodno stanje.','Could not back up %s before replacing it.'=>'Nije moguće napraviti sigurnosnu kopiju %s prije zamjene.','Could not move %s into place.'=>'Nije moguće premjestiti %s na odredište.','Could not read %s back after moving it into place.'=>'Nije moguće ponovo pročitati %s nakon premještanja na mjesto.','English (United States)'=>'Engleski (Sjedinjene Američke Države)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest nije dostupan: %s','could not read _manifest.json: %s'=>'nije moguće pročitati _manifest.json: %s','failed to parse _manifest.json: %s'=>'nije uspjelo parsiranje _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json ima neočekivanu strukturu','Could not create the package archive.'=>'Nije moguće kreirati arhivu paketa.','No writable temporary directory is available for packaging.'=>'Nema dostupnog direktorija za privremene datoteke u koji je moguće pisati za pakovanje.','A file in the component could not be read, so it was not packaged.'=>'Datoteka u komponenti nije mogla biti pročitana, pa nije upakovana.','Only plugins and themes can be packaged.'=>'Mogu se pakovati samo dodaci i teme.','The component\'s main file was not found.'=>'Glavna datoteka komponente nije pronađena.','The component is not inside the plugins or themes directory.'=>'Komponenta nije unutar direktorija dodataka ili tema.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim je ostao bez vremena za ovaj korak i nastavit će pri sljedećoj provjeri.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim nije mogao verifikovati ovu stranicu, pa se ništa neće preuzeti niti instalirati dok verifikacija ne uspije.','Registration response was missing required fields.'=>'Odgovoru na registraciju nedostaju obavezna polja.','No pending challenge to verify.'=>'Nema izazova na čekanju za verifikaciju.','Verify response was missing site_token.'=>'U odgovoru na verifikaciju nedostajao je site_token.','No site id is on file to rotate a token for.'=>'Nema spremljenog ID-a stranice za rotiranje tokena.','Rotate-token response was missing site_token.'=>'U odgovoru na rotiranje tokena nedostajao je site_token.','nonce must be a hexadecimal string.'=>'nonce mora biti heksadecimalni niz.','No pending challenge for this nonce.'=>'Nema izazova na čekanju za ovaj nonce.','Too many requests.'=>'Previše zahtjeva.','The service asked this site to wait before syncing again.'=>'Servis je zatražio da ova stranica pričeka prije ponovne sinhronizacije.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Ova stranica ima %1$d komponenti na %2$d jezika, što zahtijeva %3$d paketa provjere; Babilim može obraditi najviše %4$d po pokretanju. Smanjite broj upravljanih jezika u Postavkama ili deaktivirajte neiskorištene dodatke i teme, zatim sada pritisnite Provjeri ponovo.','Babilim could not finish checking this site.'=>'Babilim nije mogao završiti provjeru ove stranice.','This site\'s address is too long for Babilim to register.'=>'Adresa ove stranice je predugačka da bi je Babilim registrovao.','This site\'s locale code is not one Babilim can register.'=>'Kod jezika ove stranice nije takav da ga Babilim može registrovati.','The download response was missing a usable location.'=>'U odgovoru na preuzimanje nedostajala je upotrebljiva lokacija.','The service\'s upload offer was incomplete.'=>'Ponuda servisa za otpremanje bila je nepotpuna.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Ova komponenta je veća nego što servis prihvata, pa se ne može otpremiti.','The packaged component could not be read.'=>'Upakovana komponenta nije mogla biti pročitana.','A part of the upload kept failing, so the upload was cancelled.'=>'Jedan dio otpremanja stalno nije uspijevao, pa je otpremanje otkazano.','Could not read: %s'=>'Nije moguće pročitati: %s']];